window.VALID_GUESSES_PACKED_IT = {
  5: "",
  6: "",
  7: "",
  8: "",
};

window.VALID_GUESSES_PACKED_EN = {
  5: "",
  6: "",
  7: "",
  8: "",
};

// Set di validazione costruiti on-demand (lazy) e messi in cache
window.VALID_GUESSES = { it: {}, en: {} };

window.getValidGuessSet = function (length, lang) {
  lang = lang === 'en' ? 'en' : 'it';
  if (!window.VALID_GUESSES[lang][length]) {
    const packed = (lang === 'en' ? window.VALID_GUESSES_PACKED_EN : window.VALID_GUESSES_PACKED_IT)[length] || '';
    const set = new Set();
    for (let i = 0; i < packed.length; i += length) set.add(packed.substr(i, length));
    ((window.DICTIONARIES[lang] || {})[length] || []).forEach(w => set.add(w));
    window.VALID_GUESSES[lang][length] = set;
  }
  return window.VALID_GUESSES[lang][length];
};

window.getAnswerList = function (length, lang) {
  lang = lang === 'en' ? 'en' : 'it';
  return ((window.DICTIONARIES[lang] || {})[length]) || [];
};
